import React, { useState } from "react";
import { Link } from "react-router-dom";

const Navbar: React.FC = () => {
  // State to control whether the navbar is collapsed or not
  const [isCollapsed, setIsCollapsed] = useState(false);

  // Toggle the collapsed state
  const toggleNavbar = () => {
    setIsCollapsed(!isCollapsed);
  };

  return (
    <div
      className={`fixed top-0 right-0 h-screen bg-gray-800 text-white flex flex-col transition-all duration-300 ${
        isCollapsed ? "w-16" : "w-64"
      }`}
    >
        <button
          onClick={toggleNavbar}
          className="text-white bg-gray-700 p-2 focus:outline-none z-10"
        >
          {isCollapsed ? "→" : "←"}
        </button>
      <nav className="flex-1 flex flex-col">
        <Link to="/" className="px-4 py-2 hover:bg-gray-700 text-center">
          {isCollapsed ? "H" : "Home"}
        </Link>
        <Link to="/login" className="px-4 py-2 hover:bg-gray-700 text-center">
          {isCollapsed ? "L" : "Login"}
        </Link>
        <Link to="/users" className="px-4 py-2 hover:bg-gray-700 text-center">
          {isCollapsed ? "U" : "Users"}
        </Link>
        <Link to="/workorderslist" className="px-4 py-2 hover:bg-gray-700 text-center">
          {isCollapsed ? "W" : "Work Orders List"}
        </Link>
        <Link to="/createworkorders" className="px-4 py-2 hover:bg-gray-700 text-center">
          {isCollapsed ? "U" : "Create Work Orders"}
        </Link>
      </nav>
    </div>
  );
};

export default Navbar;
